"""Runtime for code generated by tools/c2py.py: simulated memory, allocator, call table.

Usage (mesh reader harness): python3 -I tools/c2py_rt.py <converted dir> <pack.bin> <record key hex>
  Runs GEO_p_CreateFromBuffer on one geometry record of an unpacked PS2 world pack and reports
  where the parse ended against the record's size, plus every function called without a
  converted version (so we know what still needs porting or a stand-in).
"""
import glob
import importlib.util
import os
import struct
import sys
from collections import Counter

PAGE = 4096
ALLOC_OBJ, ALLOC_VT, ALLOC_FN = 0x00F00000, 0x00F00100, 0x0A110C00  # fake allocator object/vtable/entry


class Runtime:
    PREF = object()  # where c2py put &P in an argument list

    def __init__(self):
        self.pages = {}
        self.heap = 0x02000000
        self.stack = 0x0E000000
        self.funcs = {}
        self.missing = Counter()
        self.globals = {'_LOA_gb_SpeedMode': 1, '_BIG_gi_ReadMode': 2, '_LOA_gb_SwapperActive': 0,
                        'piRam004efd28': ALLOC_OBJ}
        self.w32(ALLOC_OBJ, ALLOC_VT)
        self.w32(ALLOC_VT + 0xC, ALLOC_FN)

    # --- memory
    def _rb(self, a):
        a &= 0xFFFFFFFF
        p = self.pages.get(a // PAGE)
        return p[a % PAGE] if p else 0

    def _wb(self, a, v):
        a &= 0xFFFFFFFF
        p = self.pages.setdefault(a // PAGE, bytearray(PAGE))
        p[a % PAGE] = v & 0xFF

    def read(self, a, n):
        a &= 0xFFFFFFFF
        out = bytearray()
        while n > 0:
            page, off = divmod(a, PAGE)
            take = min(n, PAGE - off)
            p = self.pages.get(page)
            out += p[off:off + take] if p else bytes(take)
            a, n = (a + take) & 0xFFFFFFFF, n - take
        return bytes(out)

    def write(self, a, data):
        if len(self.pages) > (512 << 20) // PAGE:  # 512 MB of simulated memory: runaway
            raise RunawaySize('simulated memory above 512 MB')
        a &= 0xFFFFFFFF
        data = memoryview(bytes(data))
        i = 0
        while i < len(data):
            page, off = divmod(a, PAGE)
            take = min(len(data) - i, PAGE - off)
            p = self.pages.setdefault(page, bytearray(PAGE))
            p[off:off + take] = data[i:i + take]
            a, i = (a + take) & 0xFFFFFFFF, i + take

    def r8(self, a): return self._rb(a)
    def r16(self, a): return int.from_bytes(self.read(a, 2), 'little')

    def r32(self, a):
        a &= 0xFFFFFFFF
        off = a % PAGE
        if off <= PAGE - 4:
            p = self.pages.get(a // PAGE)
            return int.from_bytes(p[off:off + 4], 'little') if p else 0
        return int.from_bytes(self.read(a, 4), 'little')
    def r64(self, a): return int.from_bytes(self.read(a, 8), 'little')
    def w8(self, a, v): self._wb(a, v)
    def w16(self, a, v): self.write(a, (int(v) & 0xFFFF).to_bytes(2, 'little'))
    def w32(self, a, v): self.write(a, (int(v) & 0xFFFFFFFF).to_bytes(4, 'little'))
    def w64(self, a, v): self.write(a, (int(v) & 0xFFFFFFFFFFFFFFFF).to_bytes(8, 'little'))
    buf32 = r32

    # --- value conversions (C casts)
    @staticmethod
    def u8(v): return int(v) & 0xFF
    @staticmethod
    def u16(v): return int(v) & 0xFFFF
    @staticmethod
    def u32(v): return int(v) & 0xFFFFFFFF
    @staticmethod
    def u64(v): return int(v) & 0xFFFFFFFFFFFFFFFF
    @staticmethod
    def s8(v): v = int(v) & 0xFF; return v - 0x100 if v & 0x80 else v
    @staticmethod
    def s16(v): v = int(v) & 0xFFFF; return v - 0x10000 if v & 0x8000 else v
    @staticmethod
    def s32(v): v = int(v) & 0xFFFFFFFF; return v - 0x100000000 if v & 0x80000000 else v
    @staticmethod
    def s64(v): v = int(v) & 0xFFFFFFFFFFFFFFFF; return v - (1 << 64) if v & (1 << 63) else v
    @staticmethod
    def f32(v): return float(v)
    f64 = f32

    # --- allocation
    def malloc(self, n):
        _check(n, 'allocation')
        a = (self.heap + 15) & ~15
        self.heap = a + max(int(n), 1)
        return a

    def alloca(self, n):
        self.stack -= (int(n) + 15) & ~15
        return self.stack

    def glob(self, name):
        return self.globals.get(name, 0)

    # --- calls
    def call(self, name, *args):
        f = self.funcs.get(name)
        if f:
            return f(self, *args)
        special = SPECIAL.get(name)
        if special:
            return special(self, *args)
        self.missing[name] += 1
        return 0

    def callptr(self, fn, *args):
        if fn == ALLOC_FN:  # allocator->Alloc(self, size)
            return self.malloc(args[1])
        self.missing[f'callptr {fn:#x}'] += 1
        return 0

    def call_p(self, name, P, *args):
        cell = self.alloca(8)
        self.w32(cell, P)
        res = self.call(name, *[cell if a is Runtime.PREF else a for a in args])
        return self.r32(cell), res


MAX_BLOCK = 64 << 20  # a larger memcpy/memset/allocation means a misread size, not real data


class RunawaySize(Exception):
    pass


def _check(n, what):
    if not 0 <= int(n) <= MAX_BLOCK:
        raise RunawaySize(f'{what} of {int(n):#x} bytes (misread size?)')


def _memcpy(rt, dst, src, n):
    _check(n, 'memcpy')
    rt.write(dst, rt.read(src, n))
    return dst


def _memset(rt, dst, v, n):
    _check(n, 'memset')
    rt.write(dst, bytes([v & 0xFF]) * n)
    return dst


def _read_matrix(rt, pp, dst, flags):
    """_LOA_ReadMatrix in speed mode without byte swapping (the disc's case), written by hand
    (its decompile is goto-heavy): 0x44 bytes copied to dst if any; nothing consumed when dst is 0
    and bit 1 of flags says the matrix is absent in speed mode."""
    if dst == 0 and (flags & 2):
        return 0
    if dst:
        _memcpy(rt, dst, rt.r32(pp), 0x44)
    rt.w32(pp, rt.r32(pp) + 0x44)
    return 0


SPECIAL = {
    'ReadAlignedLong': lambda rt, a: rt.r32(a), 'ReadAlignedFloat': lambda rt, a: rt.r32(a),
    'ReadAlignedShort': lambda rt, a: rt.r16(a), 'LOA_IsSwapperActive': lambda rt: 0,
    'LOA_IsBinaryData': lambda rt: 1, 'GRO_Struct_Init__FP16GRO_tdst_Struct_i': lambda rt, *a: 0,
    'CONCAT11': lambda rt, a, b: ((a & 0xFF) << 8) | (b & 0xFF),
    'ps2memcpy': _memcpy, 'memcpy': _memcpy, 'ps2memset': _memset, 'memset': _memset,
    '_LOA_ReadMatrix': _read_matrix,
    'InitAllocator__Q23ubi3MemFQ33ubi3Mem14AllocatorUsage': lambda rt, *a: ALLOC_OBJ,
    'GetAllocator__Q23ubi3MemFQ33ubi3Mem14AllocatorUsage': lambda rt, *a: ALLOC_OBJ,
}


def load_funcs(rt, directory):
    for path in sorted(glob.glob(os.path.join(directory, '*.py'))):
        spec = importlib.util.spec_from_file_location(os.path.basename(path)[:-3], path)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        for name, obj in vars(mod).items():
            if callable(obj) and not name.startswith('__'):
                rt.funcs[name] = obj


def parse_record(directory, pack, off, size, funcs=None):
    """Run the converted loader on one record; returns (end offset, runtime)."""
    rt = Runtime()
    if funcs is None:
        load_funcs(rt, directory)
    else:
        rt.funcs = funcs
    base = 0x01000000
    rt.write(base, pack[off:off + size])
    cell = rt.alloca(8)
    rt.w32(cell, base + 8)
    version = struct.unpack_from('<I', pack, off + 4)[0]
    rt.funcs['GEO_p_CreateFromBuffer__FP16GRO_tdst_Struct_PPcP15WOR_tdst_World_Ui'](rt, 0, cell, 0, version)
    return rt.r32(cell) - base, rt


def main(argv):
    if argv[2] == 'all':  # every geometry record (type 1) in the pack
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import jadetex
        pack = open(argv[1], 'rb').read()
        rt0 = Runtime()
        load_funcs(rt0, argv[0])
        ok = bad = err = 0
        for key, (off, size) in sorted(jadetex.records(pack).items()):
            if size < 8 or struct.unpack_from('<I', pack, off)[0] != 1 or not 0 < struct.unpack_from('<I', pack, off + 4)[0] < 16:
                continue
            try:
                end, _ = parse_record(argv[0], pack, off, size, rt0.funcs)
                if end == size:
                    ok += 1
                else:
                    bad += 1
                    print(f'  {key:08x}: ended at {end:#x} of {size:#x}')
            except Exception as e:
                err += 1
                print(f'  {key:08x}: {type(e).__name__}: {str(e)[:80]}')
        print(f'geometry records: {ok} exact, {bad} wrong length, {err} errors')
        return
    directory, pack_path, key = argv[0], argv[1], int(argv[2], 16)
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    import jadetex
    pack = open(pack_path, 'rb').read()
    off, size = jadetex.records(pack)[key]
    rt = Runtime()
    load_funcs(rt, directory)
    base = 0x01000000
    rt.write(base, pack[off:off + size])
    gro_type, version = struct.unpack_from('<II', pack, off)
    cell = rt.alloca(8)
    rt.w32(cell, base + 8)  # GRO_l_Struct_Load consumed type + version
    obj = rt.funcs['GEO_p_CreateFromBuffer__FP16GRO_tdst_Struct_PPcP15WOR_tdst_World_Ui'](rt, 0, cell, 0, version)
    end = rt.r32(cell) - base
    print(f'record {key:08x}: type {gro_type}, version {version}, size {size:#x}; parse ended at {end:#x} '
          f'({"EXACT" if end == size else "short by %#x" % (size - end) if end < size else "past the end by %#x" % (end - size)})')
    print('object at', hex(obj) if obj else obj)
    for name, n in rt.missing.most_common():
        print(f'  not converted: {name} x{n}')


if __name__ == '__main__':
    main(sys.argv[1:])
